package at.andrew.squashtap;

import android.app.*;import android.content.*;import android.view.*;import android.widget.*;
import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;
import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowDialog;import org.robolectric.util.ReflectionHelpers;
import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class) @Config(sdk=34,application=Application.class,qualifiers="w233dp-h233dp-round") @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.LEGACY)
public class RetirementAndTransferUiTest {
    private ActivityController<MainActivity> controller;private MainActivity activity;private SharedPreferences preferences;private QueuedTasks tasks;
    private static class QueuedTasks extends AbstractExecutorService{final List<Runnable> queued=new ArrayList<>();boolean closed;public void execute(Runnable r){queued.add(r);}public void shutdown(){closed=true;}public List<Runnable> shutdownNow(){closed=true;return queued;}public boolean isShutdown(){return closed;}public boolean isTerminated(){return closed;}public boolean awaitTermination(long t,TimeUnit u){return closed;}}
    @Before public void launch(){preferences=RuntimeEnvironment.getApplication().getSharedPreferences("squash",0);MatchBook b=new MatchBook(new MatchState("current",3));b.add(0);b.add(1);b.add(0);save(b,true);open();}
    private void save(MatchBook b,boolean active){OpponentDirectory d=new OpponentDirectory();String id=d.add("Alice");d.assign(b.current().id(),id);preferences.edit().clear().putString("match_book",b.encode()).putString("opponent_book",d.encode()).putBoolean("asked_match_notification",true).commit();if(active)preferences.edit().putString(MatchDisplayPolicy.ACTIVE_MATCH,b.current().id()).commit();}
    private void open(){controller=Robolectric.buildActivity(MainActivity.class).setup();activity=controller.get();tasks=new QueuedTasks();ReflectionHelpers.setField(activity,"tasks",tasks);}
    private void close(){Dialog d=ShadowDialog.getLatestDialog();if(d!=null)d.dismiss();if(controller!=null){controller.pause().stop().destroy();controller=null;}}
    @After public void finish(){close();}
    private List<View> all(View v){List<View> out=new ArrayList<>();out.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)out.addAll(all(((ViewGroup)v).getChildAt(i)));return out;}
    private List<View> all(){return all(ShadowDialog.getLatestDialog().getWindow().getDecorView());}
    private Button button(String text){for(View v:all())if(v instanceof Button&&((Button)v).getText().toString().split("\n",2)[0].equals(text))return (Button)v;throw new AssertionError("Missing button: "+text);}
    private boolean hasButton(String text){for(View v:all())if(v instanceof Button&&((Button)v).getText().toString().split("\n",2)[0].equals(text))return true;return false;}
    private boolean contains(String text){for(View v:all())if(v instanceof TextView&&((TextView)v).getText().toString().contains(text))return true;return false;}
    private void click(String text){button(text).performClick();}
    private MatchBook book(){return MatchBook.decode(preferences.getString("match_book",""));}
    private OpponentDirectory names(){return OpponentDirectory.decode(preferences.getString("opponent_book",""));}
    private void matchMenu(){activity.action(TouchTargets.MENU);click("Current match");}
    private JSONObject phone(boolean explicit)throws Exception{MatchBook b=book();OpponentDirectory d=names();JSONArray list=TransferClient.catalog(d);list.put(new JSONObject().put("id","new-name").put("name","Bob").put("archived",false));JSONObject p=new JSONObject().put("baseDirectory",TransferClient.base(b,d)).put("currentMatchId",b.current().id()).put("currentOpponentId","new-name").put("opponents",list).put("csv","");if(explicit)p.put("changeCurrentOpponent",true);return p;}
    private void preview(JSONObject p)throws Exception{TransferClient.Session s=new TransferClient.Session();s.expiresAt=System.currentTimeMillis()+600000;ReflectionHelpers.setField(activity,"transfer",s);ReflectionHelpers.callInstanceMethod(activity,"previewTransfer",ReflectionHelpers.ClassParameter.from(JSONObject.class,p),ReflectionHelpers.ClassParameter.from(TransferClient.Session.class,s));}
    private void completeCurrent(){close();MatchBook b=book();while(!b.current().complete()){while(b.current().game().winner()==-1)b.add(0);if(!b.current().complete())b.nextGame();}save(b,false);open();}
    @Test public void endingAMatchIsOnlyInTheMatchSubmenu(){activity.action(TouchTargets.MENU);assertFalse(hasButton("Save retirement result"));click("Current match");assertFalse(hasButton("Save retirement result"));click("Match options");assertTrue(hasButton("Save retirement result"));click("Save retirement result");assertTrue(hasButton("I quit"));assertTrue(hasButton("Opponent quit"));assertNull(button("Cancel").getBackgroundTintList());}
    @Test public void cancellingEitherRetirementStepPreservesScoreOpponentAndSession(){String before=book().encode(),names=names().encode();matchMenu();click("Match options");click("Save retirement result");click("Cancel");assertEquals(before,book().encode());click("Save retirement result");click("I quit");click("Cancel");click("Cancel");assertEquals(before,book().encode());assertEquals(names,names().encode());assertEquals("current",preferences.getString(MatchDisplayPolicy.ACTIVE_MATCH,""));}
    @Test public void quittingSavesALossWithPartialScoreAndStopsActivePowerUse(){matchMenu();click("Match options");click("Save retirement result");click("I quit");assertTrue(contains("You quit"));click("Save retirement");MatchBook b=book();assertTrue(b.current().retired());assertEquals(1,b.current().winner());assertEquals(2,b.result("current").points(0,0));assertEquals(1,b.result("current").points(0,1));assertEquals(0,b.result("current").gamesWon(1));assertTrue(contains("Me retired"));assertTrue(contains("unfinished"));assertNotNull(button("Undo retirement"));assertFalse(preferences.contains(MatchDisplayPolicy.ACTIVE_MATCH));assertEquals(0,activity.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
    @Test public void opponentQuittingCountsAsWinEvenWhenTheirPartialScoreLeads(){close();MatchBook b=new MatchBook(new MatchState("current",3));for(int i=0;i<3;i++)b.add(1);save(b,true);open();matchMenu();click("Match options");click("Save retirement result");click("Opponent quit");click("Save retirement");assertEquals(0,book().current().winner());assertTrue(contains("Opponent retired"));activity.action(TouchTargets.MENU);click("Statistics");assertTrue(contains("Won: 1 · Lost: 0"));assertTrue(contains("Won: 0 · Lost: 0"));assertTrue(contains("For: 0 · Against: 3"));}
    @Test public void undoRetirementReopensWithoutUndoingAPointOrRestartingTheSession(){matchMenu();click("Match options");click("Save retirement result");click("Opponent quit");click("Save retirement");shadowOf(RuntimeEnvironment.getApplication()).clearStartedServices();click("Undo retirement");assertFalse(book().current().complete());assertEquals(2,book().current().game().blue());assertEquals(1,book().current().game().red());assertEquals(0,book().count());assertFalse(preferences.contains(MatchDisplayPolicy.ACTIVE_MATCH));assertNull(shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService());matchMenu();assertNotNull(button("Resume match"));}
    @Test public void endingAPausedMatchClearsThePauseStateAndKeepsTheSavedOutcome(){matchMenu();click("Pause match");assertTrue(preferences.getBoolean("match_paused",false));matchMenu();click("Match options");click("Save retirement result");click("Opponent quit");click("Save retirement");assertTrue(book().current().retired());assertEquals(0,book().current().winner());assertFalse(preferences.getBoolean("match_paused",true));assertFalse(preferences.contains(MatchDisplayPolicy.ACTIVE_MATCH));assertTrue(contains("Opponent retired"));}
    @Test public void b2MigrationBacksUpOnceAndKeepsCurrentResultAndCounters()throws Exception{close();String old=new String(Files.readAllBytes(Paths.get("android/test-fixtures/book-v2-completed.txt")),StandardCharsets.UTF_8).trim();preferences.edit().clear().putString("match_book",old).commit();open();assertEquals(old,preferences.getString("match_book_v2_backup",""));assertTrue(preferences.getString("match_book","").startsWith("B4:"));assertEquals(2,book().count());assertEquals(3,book().result("v2-current").number);String upgraded=book().encode();close();open();assertEquals(old,preferences.getString("match_book_v2_backup",""));assertEquals(upgraded,book().encode());}
    @Test public void catalogOnlyPhoneSyncCannotRenameTheLastCompletedMatch()throws Exception{completeCurrent();String before=book().encode(),id=names().opponentId("current");preview(phone(false));assertTrue(contains("assignment is unchanged"));click("Apply changes");assertEquals(before,book().encode());assertEquals(id,names().opponentId("current"));assertEquals("Bob",names().get("new-name").name);}
    @Test public void aNonBooleanOptInCannotAccidentallyAssignANewName()throws Exception{JSONObject p=phone(false).put("changeCurrentOpponent","true");MatchCsv.Plan plan=TransferClient.preview(p,book(),names());assertEquals(names().opponentId("current"),plan.directory.opponentId("current"));}
    @Test public void explicitPhoneAssignmentShowsTheCompletedMatchChangeBeforeApply()throws Exception{completeCurrent();String before=book().encode();preview(phone(true));assertTrue(contains("Last completed match opponent change"));assertTrue(contains("Alice → Bob"));click("Apply changes");assertEquals("Bob",names().nameFor("current"));assertEquals(before,book().encode());}
    @Test public void browseOnPhoneIsAvailableInResultsAndDoesNotChangeAnyScore(){String before=book().encode();activity.action(TouchTargets.MENU);click("Results (0)");click("Options");click("View results on phone");assertTrue(contains("Preparing phone link"));assertEquals(1,tasks.queued.size());assertEquals(before,book().encode());}
    @Test public void fullSnapshotIncludesRetirementsAndAnExplicitOverallScope()throws Exception{MatchBook b=book();b.retire(1);OpponentDirectory d=names();JSONObject p=TransferClient.snapshot(new TransferClient.Session(),b,d,b.newestFirst());assertTrue(p.getBoolean("supportsRetirement"));assertTrue(p.getBoolean("currentMatchComplete"));assertEquals(1,p.getInt("totalResults"));assertEquals(1,MatchCsv.parse(p.getString("csv")).get(0).result.retiredPlayer);}
}
